def answer_position_counts(items: list[dict] | None = None) -> dict[int, int]:
    counts = {0: 0, 1: 0, 2: 0, 3: 0}
    for item in items or CHAPTER4_STAGING_QUESTIONS:
        counts[int(item["correct"])] += 1
    return counts


